insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 2, 6, 'Portanto, assim como recebestes Cristo Jesus, o Senhor, assim também andai nele;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 2, 7, 'com raízes firmes e edificados nele, e confirmados na fé, como fostes ensinados, abundando nela com gratidão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 2, 8, 'Cuidado que ninguém vos tome cativos por meio de filosofias e de enganos vãos, conforme a tradição humana, conforme os elementos do mundo, e não conforme Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 2, 9, 'Pois nele habita corporalmente toda a plenitude da divindade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 2, 10, 'E vós vos tornais plenos nele, que é o cabeça de todo governo e autoridade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 2, 11, 'Nele também fostes circuncidados com uma circuncisão não feita por mãos, [mas sim] , no abandono do corpo dos pecados da carne, pela circuncisão de Cristo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 2, 12, 'sepultados com ele no batismo, no qual também com ele fostes ressuscitados pela fé no poder de Deus, que o ressuscitou dos mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 2, 13, 'E quando vós estáveis mortos em pecados, na incircuncisão da vossa carne, [Deus] vos deu vida juntamente com ele, perdoando-vos todas as ofensas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 2, 14, 'Ele riscou a certidão de nossa dívida em ordenanças, a qual era contra nós, e a removeu, cravando-a na cruz;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 2, 15, 'ele despojou os domínios e autoridades, publicamente os envergonhou, e nela triunfou sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 2, 16, 'Portanto, ninguém vos julgue pelo comer, ou pelo beber, ou por causa de celebração [religiosa] , ou pela lua nova, ou pelos sábados;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 2, 17, 'essas coisas são a sombra das coisas futuras, mas a realidade pertence a Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 2, 18, 'Ninguém, pois, se faça de juiz contra vós, insistindo nos pretextos de “humildade” e de “culto aos anjos” , envolvendo-se em coisas que nunca viu, vangloriando-se em sua mentalidade carnal,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 2, 19, 'e não se ligando à cabeça, da qual todo o corpo, suprido e organizado pelas juntas e ligamentos, vai crescendo com o crescimento da parte de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 2, 20, 'Portanto, se estais mortos com Cristo para os elementos do mundo, por que vos sujeitais a ordenanças como se vivêsseis no mundo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 2, 21, '[tais como] : “não pegues”, “não proves”, “não toques”?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 2, 22, 'Todas elas se acabam com o uso, e se baseiam em mandamentos e doutrinas humanas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 2, 23, 'Elas realmente têm aparência de sabedoria em culto voluntário, humildade, e tratamento severo ao corpo; mas não têm valor algum contra a satisfação da carne.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 3, 1, 'Portanto, se fostes ressuscitados com Cristo, buscai as coisas de cima, onde Cristo está sentado à direita de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 3, 2, 'Pensai nas coisas de cima, não nas que [estão] na terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 3, 3, 'Pois já morrestes, e a vossa vida está escondida com Cristo em Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 3, 4, 'Quando Cristo, [que é] a nossa vida, se manifestar, então também vós vos manifestareis com ele em glória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 3, 5, 'Portanto, mortificai as partes carnais que há em vós que são terrenas; [são elas] : o pecado sexual, a impureza, a paixão depravada, o desejo maligno, e a ganância, que é idolatria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 3, 6, 'Por causa delas que a ira de Deus vem sobre os filhos da desobediência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 3, 7, 'Nessas coisas também vós andastes antes, quando vivíeis nelas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 3, 8, 'Mas agora, abandonai, vós também, todas [estas coisas] : a ira, a fúria, a malícia, a maledicência, e as palavras vergonhosas da vossa boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 3, 9, 'Não mintais uns aos outros, pois já vos despistes do velho ser humano com os seus costumes,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 3, 10, 'e vos revestistes do novo, que se renova em conhecimento, conforme a imagem daquele que o criou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 3, 11, 'Nisso não há grego, nem judeu, nem circunciso, nem incircunciso, bárbaro, cita, escravo, [nem] livre; mas Cristo é tudo, e em todos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 3, 12, 'Por isso, como escolhidos de Deus, santos e amados, revesti-vos de sentimentos de misericórdia, bondade, humildade, mansidão, e paciência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 3, 13, 'Suportai-vos uns aos outros, e perdoai-vos uns aos outros, se alguém tiver queixa contra outro. Como Cristo vos perdoou, assim também [fazei] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 3, 14, 'E acima de tudo isto, [revesti-vos] do amor, que é o vínculo da perfeição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 3, 15, 'E a paz de Deus, para a qual também fostes chamados em um [só] corpo, governe em vossos corações, e sede gratos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 3, 16, 'A palavra de Cristo habite abundantemente em vós com toda sabedoria, ensinando-vos e advertindo-vos uns aos outros; e cantai ao Senhor com salmos, hinos, e cânticos espirituais, com graça no vosso coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 3, 17, 'E tudo quanto fizerdes, por palavras ou por obras, [fazei] tudo no nome do Senhor Jesus, dando por meio dele graças ao Deus e Pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 3, 18, 'Mulheres, sede submissas aos vossos próprios maridos, como convém no Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 3, 19, 'Maridos, amai às esposas, e não as trateis amargamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 3, 20, 'Filhos, obedecei em tudo aos pais, porque isso é agradável ao Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 3, 21, 'Pais, não provoqueis aos vossos filhos, para que não percam o ânimo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 3, 22, 'Escravos, obedecei em tudo aos [vossos] senhores segundo a carne, não servindo apenas quando observados, como que para satisfazer às pessoas, mas sim, com sinceridade de coração, temendo a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 3, 23, 'E tudo quanto fizerdes, fazei de coração, como para o Senhor, e não para as pessoas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 3, 24, 'Pois sabeis que recebereis do Senhor a recompensa da herança, porque servis ao Senhor Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 3, 25, 'Mas aquele que fizer injustiça receberá conforme a injustiça que cometer; e não há acepção de pessoas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 4, 1, 'Senhores, procedei de maneira justa e imparcial com os [vossos] servos, sabendo que também vós tendes um Senhor nos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 4, 2, 'Perseverai na oração, vigiando nela com gratidão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 4, 3, 'Orai também ao mesmo tempo por nós, para que Deus nos abra uma porta para a palavra, para que falemos do mistério de Cristo, [mistério] pelo qual estou preso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 4, 4, 'Para que eu o anuncie claramente, como devo falar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 4, 5, 'Convivei com sabedoria com os que estão de fora, aproveitando o tempo oportuno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 4, 6, 'A vossa palavra [seja] sempre com graça, temperada com sal, para que saibais como deveis responder a cada um.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 4, 7, 'Tíquico, irmão amado, fiel trabalhador e colaborador no Senhor, vos fará saber tudo o que vem acontecendo comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 4, 8, 'Foi para isso que eu o enviei até vós, para que saiba como estais, e console os vossos corações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 4, 9, 'Juntamente com ele [está] Onésimo, irmão fiel e amado, que é um de vós. Eles vos farão saber tudo o que está havendo por aqui.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 4, 10, 'Aristarco, que está preso comigo, vos saúda; e também Marcos, primo de Barnabé. Acerca dele, já recebestes ordens; se ele for até vós, recebei-o.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 4, 11, 'E também Jesus, chamado Justo. Dentre os circuncisos, esses [são] os únicos cooperadores [meus] no Reino de Deus, e têm sido consolação para mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 4, 12, 'Epafras, que é um de vós, servo de Cristo, vos saúda. Ele sempre luta por vós em orações, para que fiqueis íntegros e plenos em toda a vontade de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 4, 13, 'Pois dou testemunho dele de que ele tem grande zelo por vós, pelos que [estão] em Laodiceia, e pelos que [estão] em Hierápolis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 4, 14, 'Lucas, o médico amado, vos saúda; e também Demas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 4, 15, 'Saudai aos irmãos que [estão] em Laodiceia, e também a Ninfas, e à igreja que está na casa dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 4, 16, 'E depois que esta carta for lida entre vós, fazei que ela também seja lida na igreja dos laodicenses, e que vós leiais também a de Laodiceia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 4, 17, 'E dizei a Árquipo: Presta atenção ao trabalho que recebeste do Senhor, para que o cumpras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 51, 'Colossenses', 'Cl', 4, 18, '[Esta] saudação [é] da minha mão, de Paulo. Lembrai-vos das minhas prisões. A graça [esteja] convosco. Amém. (Escrita de Roma aos colossenses, e enviada por Tíquico e Onésimo.)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 1, 1, 'Paulo, Silvano, e Timóteo, à igreja dos tessalonicenses, em Deus Pai, e no Senhor Jesus Cristo; haja convosco a graça e a paz de Deus, nosso Pai, e do Senhor Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 1, 2, 'Sempre damos graças a Deus por todos vós, fazendo menção de vós em nossas orações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 1, 3, 'E, diante do nosso Deus e Pai, nós nos lembramos sem cessar da obra da vossa fé, do trabalho do amor, e da firmeza da esperança no nosso Senhor Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 1, 4, 'Sabemos, irmãos amados por Deus, que [por ele] fostes escolhidos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 1, 5, 'pois o nosso evangelho não foi até vós somente com palavras, mas também com poder, com o Espírito Santo, e com plena certeza; assim como sabeis de que maneira estivemos entre vós para o vosso benefício.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 1, 6, 'E vos tornastes imitadores nossos e do Senhor. [Mesmo] em meio a muita aflição, recebestes a palavra com a alegria do Espírito Santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 1, 7, 'Dessa maneira vos tornastes referências a todos os crentes na Macedônia e Acaia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 1, 8, 'Pois de vós ressoou a palavra do Senhor, não somente na Macedônia e Acaia, mas a vossa fé em Deus também se espalhou em todo lugar, de tal maneira que não precisamos falar coisa alguma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 1, 9, 'Pois eles mesmos anunciam como fomos recebidos por vós, e como vos convertestes, deixando os ídolos, para servir ao Deus vivo e verdadeiro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 1, 10, 'e para esperar dos céus o seu Filho, a quem ele ressuscitou dos mortos: Jesus, que nos livra da ira futura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 2, 1, 'Pois vós mesmos, irmãos, sabeis que a nossa passagem por entre vós não foi inútil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 2, 2, 'Porém, mesmo que antes, em Filipos, tenhamos sofrido e sido maltratados, como sabeis, tivemos no nosso Deus ousadia para vos falar o evangelho de Deus em meio a muita oposição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 2, 3, 'Pois a nossa exortação não [foi] com engano, nem com impureza, nem fraude;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 2, 4, 'mas, como fomos aprovados por Deus para que o evangelho nos fosse confiado, assim falamos; não para agradar as pessoas, mas sim a Deus, que prova os nossos corações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 2, 5, 'Pois, como sabeis, nunca usamos palavras de lisonja, nem pretexto de ganância; Deus é testemunha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 2, 6, 'Não buscamos a glória humana, nem de vós, nem de outros, ainda que tínhamos autoridade, como apóstolos de Cristo, para demandar de vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 2, 7, 'Porém fomos suaves entre vós, como uma mãe que dá carinho aos seus filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 2, 8, 'Assim nós, tendo tanta afeição por vós, queríamos de boa vontade compartilhar convosco não somente o evangelho de Deus, mas também as nossas próprias almas, porque éreis queridos por nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 2, 9, 'Pois vos lembrais, irmãos, do nosso trabalho e fadiga; porque enquanto vos pregávamos o evangelho de Deus, trabalhávamos noite e dia para que não fôssemos um peso para vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 2, 10, 'Vós e Deus [sois] testemunhas de como foi santa, justa, e irrepreensível a maneira da qual nos comportamos convosco, que credes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 2, 11, 'Assim como sabeis que, como um pai aos seus filhos, exortávamos, consolávamos, e testemunhávamos a cada um de vós,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 2, 12, 'para que andásseis de maneira digna diante de Deus, que vos chama para o seu reino e glória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 2, 13, 'Por isso também agradecemos sem cessar a Deus, que, quando recebestes a palavra da Deus pregada por nós, a recebestes, não [como] palavra de homens, mas (conforme em verdade é) [como] a palavra de Deus, a qual também opera em vós, que credes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 2, 14, 'Pois vós, irmãos, vos tornastes imitadores das igrejas de Deus que estão na Judeia em Cristo Jesus; porque também sofrestes as mesmas coisas dos vossos próprios compatriotas, como também eles dos judeus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 2, 15, 'que também mataram o Senhor Jesus e os seus próprios profetas, e nos perseguiram, e não agradam a Deus, e são contrários a todos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 2, 16, 'eles nos impedem de falar aos gentios, para que sejam salvos. Assim eles estão se enchendo constantemente de pecados, mas, por fim, ira veio sobre eles até o fim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 2, 17, 'Porém, irmãos, quando nos separamos de vós por algum tempo, em presença, não no coração, buscamos mais, com muito desejo, ver o vosso rosto;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 2, 18, 'por isso quisemos, pelo menos eu, Paulo, vos visitar uma vez e outra; mas Satanás nos impediu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 2, 19, 'Pois, qual é nossa esperança, alegria, ou coroa de orgulho, diante do nosso Senhor Jesus Cristo na sua vinda? Acaso não sois vós?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 2, 20, 'Porque vós sois o nosso orgulho e alegria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 3, 1, 'Por isso, como não podíamos mais suportar, decidimos ficar sozinhos em Atenas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 3, 2, 'e enviamos Timóteo, nosso irmão e servidor de Deus, e cooperador nosso no Evangelho de Cristo, para vos fortalecer e vos encorajar quanto a vossa fé;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 3, 3, 'a fim de que ninguém se abale por essas aflições; pois vós mesmos sabeis que para isso fomos destinados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 3, 4, 'Pois quando ainda estávamos convosco vós dizíamos com antecedência que seríamos afligidos, como aconteceu, e vós sabeis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 3, 5, 'Por isso, como não podia mais suportar, eu [o] enviei para saber de vossa fé. [Eu temia] que o tentador houvesse vos tentado, e o nosso trabalho houvesse sido inútil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 3, 6, 'Mas agora, depois que Timóteo voltou a nós da vossa presença, e nos trouxe boas notícias da vossa fé e amor, e de como sempre tendes boa lembrança de nós, e desejais muito nos ver, como também nós a vós;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 3, 7, 'por isso, irmãos, ficamos consolados acerca de vós em toda a nossa aflição e necessidade, pela vossa fé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 3, 8, 'Pois agora vivemos, se vós estais firmes no Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 3, 9, 'Pois como agradecemos a Deus por vós, por toda a alegria com que nos alegramos por vossa causa, diante do nosso Deus!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 3, 10, 'E de noite e de dia com extrema intensidade oramos para que possamos ver o vosso rosto, e supramos o que falta na vossa fé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 3, 11, 'E que o mesmo Deus, nosso Pai, e o nosso Senhor Jesus Cristo, preparem o nosso caminho até vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 3, 12, 'E o Senhor vos faça crescer e exceder em amor uns pelos outros, e por todos, à semelhança de nós por vós;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 3, 13, 'a fim de que fortaleça os vossos corações, irrepreensíveis em santidade diante do nosso Deus e Pai, na vinda do nosso Senhor Jesus Cristo com todos os seus santos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 4, 1, 'Portanto, irmãos, no restante, vos rogamos e exortamos no Senhor Jesus, que, assim como recebestes de nós como deveis andar e agradar a Deus, que façais [assim] cada vez mais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 4, 2, 'Pois vós sabeis quais mandamentos vos demos pelo Senhor Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 4, 3, 'Pois esta é a vontade de Deus: a vossa santificação, que não pratiqueis pecado sexual;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 4, 4, 'que cada um de vós saiba ser ter o seu instrumento em santidade e honra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 4, 5, 'não na paixão do desejo malicioso, como os gentios que não conhecem Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 4, 6, 'Ninguém oprima ou engane ao seu irmão nisso, porque o Senhor é vingador de todas essas coisas, como também antes vos dissemos e demos testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 4, 7, 'Pois Deus não nos chamou para a impureza, mas sim para a santificação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 4, 8, 'Portanto quem rejeita [isso] , rejeita não ao ser humano, mas sim a Deus, que nos deu também o seu Espírito Santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 4, 9, 'Mas quanto ao amor fraternal, não precisais que eu vos escreva, pois vós mesmos estais instruídos por Deus que vos ameis uns aos outros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 4, 10, 'Pois, de fato, [já] fazeis assim a todos os irmãos de toda a Macedônia. Porém, irmãos, vos exortamos que façais[isso] ainda mais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 4, 11, 'E procurai viver quietos, trantando dos vossos próprios assuntos, e trabalhando com as vossas próprias mãos, como já vos mandamos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 4, 12, 'para que andeis de maneira respeitosa com os que estão de fora, e não necessiteis de nada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 4, 13, 'Mas irmãos, não quero que desconheçais acerca dos que morreram, para que não vos entristeçais como os outros que não têm esperança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 4, 14, 'Pois, se cremos que Jesus morreu e ressuscitou, assim também aos que morreram em Jesus, Deus os trará de volta com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 4, 15, 'Pois dizemos isto pela palavra do Senhor, que nós, os que ficarmos vivos até a vinda do Senhor, não iremos antes dos que morreram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 4, 16, 'Pois o mesmo Senhor descerá do céu com grande aclamação, com voz de arcanjo, e com trombeta de Deus; e os que morreram em Cristo ressuscitarão primeiro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 4, 17, 'Em seguida nós, os que ficarmos vivos, seremos arrebatados juntamente com eles nas nuvens, para encontrar o Senhor no ar, e assim estaremos com o Senhor para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 4, 18, 'Portanto consolai-vos uns aos outros com essas palavras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 5, 1, 'Mas irmãos, acerca dos tempos e das estações, não necessitais de que eu vos escreva;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 5, 2, 'pois vós mesmos bem sabeis que o dia do Senhor virá como um ladrão de noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 5, 3, 'Pois quando disserem: “Paz e segurança”, então virá sobre eles repentina destruição, como as dores de parto da grávida, e de maneira nenhuma escaparão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 5, 4, 'Mas vós, irmãos, não estais em trevas, para que aquele dia vos tome de surpresa como um ladrão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 5, 5, 'Todos vós sois filhos da luz e filhos do dia; não somos da noite nem das trevas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 5, 6, 'Portanto, não durmamos, como os outros; em vez disso, vigiemos e sejamos sóbrios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 5, 7, 'Pois os que dormem, dormem de noite; e os que ficam bêbados embebedam-se de noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 5, 8, 'Mas nós, que somos do dia, sejamos sóbrios, e nos vistamos da couraça da fé e do amor, e do capacete da esperança da salvação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 5, 9, 'Porque Deus não nos destinou para a ira, mas, sim, para obtermos a salvação, por meio do nosso Senhor Jesus Cristo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 5, 10, 'que morreu por nós, a fim de que, se estivermos vigiando ou dormindo, nós vivamos juntamente com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 5, 11, 'Portanto exortai-vos uns aos outros, e edificai-vos uns aos outros, como já fazeis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 5, 12, 'Irmãos, nós vos rogamos que reconheçais os que trabalham entre vós, e que lideram sobre vós no Senhor, e vos advertem;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 5, 13, 'e os estimai muito com amor, por causa do trabalho deles. Tende paz entre vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 5, 14, 'Rogamo-vos também, irmãos, que advirtais os desordeiros, consoleis os de pouco ânimo, apoieis aos fracos, e tenhais paciência com todos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 5, 15, 'Tende cuidado para que ninguém retribua o mal com o mal, mas sempre segui o bem, tanto uns com os outros, como com todos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 5, 16, 'Alegrai-vos sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 5, 17, 'Orai sem cessar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 5, 18, 'Agradecei em tudo, pois essa é a vontade de Deus em Cristo Jesus para vós mesmos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 5, 19, 'Não apagueis o Espírito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 5, 20, 'Não desprezeis as profecias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 5, 21, 'Examinai tudo, e mantende o que é bom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 5, 22, 'Não haja entre vós qualquer forma de mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 5, 23, 'E o próprio Deus da paz vos santifique em tudo; e que todo o vosso espírito, alma e corpo sejam preservados irrepreensíveis na vinda do nosso Senhor Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 5, 24, 'Fiel é aquele que vos chama, e ele também [o] fará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 5, 25, 'Irmãos, orai por nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 5, 26, 'Saudai a todos os irmãos com beijo santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 5, 27, 'Eu vos mando pelo Senhor que esta carta seja lida a todos os santos irmãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 52, '1 Tessalonicenses', '1Ts', 5, 28, 'A graça de nosso Senhor Jesus Cristo [seja] convosco. Amém. [A primeira carta aos tessalonicenses foi escrita de Atenas]'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 1, 1, 'Paulo, e Silvano, e Timóteo, à igreja dos tessalonicenses, em Deus nosso Pai, e no Senhor Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 1, 2, '[Haja entre vós] graça e paz de nosso Pai, e do Senhor Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 1, 3, 'Nós sempre devemos dar graças a Deus por vós, irmãos, como é o correto, porque vossa fé cresce muito, e o amor de cada um de todos vós pelos outros é cada vez maior;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 1, 4, 'De maneira que nós mesmos nos orgulhamos de vós nas igrejas de Deus, por causa de vossa paciência e fé, em todas as vossas perseguições aflições que suportais;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 1, 5, '[Que é] prova clara do justo julgamento de Deus, para que sejais considerados dignos do Reino de Deus, pelo qual também sofreis;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 1, 6, 'Pois é justo diante de Deus pagar com aflição aos que vos afligem;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 1, 7, 'E a vós que sois afligidos, alívio conosco, quando o Senhor Jesus aparecer do céu com os anjos de seu poder,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 1, 8, 'Com labareda de fogo, vingando os que não conhecem a Deus, e os que não obedecem ao Evangelho do nosso Senhor Jesus Cristo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 1, 9, 'Os quais serão punidos com o castigo da eterna perdição, [longe] da face do Senhor, e da glória de sua força;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 1, 10, 'Quando ele vier para ser glorificado em seus santos, e naquele dia se fazer admirável em todos os que creem (porque nosso testemunho entre vós foi crido).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 1, 11, 'Por isso que também sempre rogamos por vós, que nosso Deus vos faça dignos do chamamento, e cumpra todo bom desejo e a obra da fé com poder.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 1, 12, 'Para que o nome de nosso Senhor Jesus Cristo seja glorificado em vós, e vós nele, segundo a graça de nosso Deus, e do Senhor Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 2, 1, 'Ora irmãos, nós vos rogamos quanto à vinda de nosso Senhor Jesus Cristo, e à nossa reunião com ele,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 2, 2, 'Que vós não vos abaleis facilmente em [vosso] entendimento, e não [vos] perturbeis, nem por espírito, nem por palavra, nem por carta como que [escrita] por nós, como se o dia de Cristo [já] estivesse perto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 2, 3, 'Ninguém vos engane em maneira nenhuma; porque [não virá esse dia] sem que primeiro venha a apostasia, e se manifeste o homem do pecado, o filho da perdição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 2, 4, 'O qual se opõe e se levanta sobre tudo o que se chama Deus, ou [sobre] tudo que é adorado; por isso ele se sentará no templo de Deus, como [se fosse] Deus, fazendo-se parecer Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 2, 5, 'Não vos lembrais, que enquanto ainda estava convosco, eu vos dizia estas coisas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 2, 6, 'E agora sabeis o que o detém, para que a seu próprio tempo seja manifestado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 2, 7, 'Porque o mistério da injustiça já opera; só [há] aquele que agora o detém, até que seja [tirado] do meio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 2, 8, 'E então será manifestado aquele injusto, ao qual o Senhor destruirá, pelo sopro de sua boca, e o aniquilará pelo aparecimento de sua vinda;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 2, 9, '[Aquele injusto] cuja vinda é conforme o agir de Satanás, com todo poder, e sinais, e milagres falsos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 2, 10, 'E com todo engano de injustiça nos que perecem; porque não receberam o amor da verdade para se salvarem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 2, 11, 'E por isso Deus lhes enviará a ação do erro, para que creiam na mentira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 2, 12, 'Para que sejam condenados todos os que não creram na verdade, mas tiveram prazer na injustiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 2, 13, 'Mas sempre devemos dar graças a Deus por vós, irmãos, que sois amados pelo Senhor, pois Deus vos escolheu desde o princípio para a salvação, em santificação do Espírito, e fé na verdade;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 2, 14, 'Para a qual ele vos chamou por meio do nosso Evangelho, para a obtenção da glória de nosso Senhor Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 2, 15, 'Portanto, irmãos, ficai firmes, e retende as tradições que vos foram ensinadas, seja por palavra, seja por carta nossa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 2, 16, 'E ele mesmo, o nosso Senhor Jesus Cristo, e nosso Deus e Pai, que nos amou e em graça nos deu uma eterna consolação e boa esperança;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 2, 17, 'Ele console vossos corações, e vos fortaleça em toda boa palavra e obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 3, 1, 'Nas demais coisas, irmãos, rogai por nós, para que a palavra do Senhor continue seu percurso, e seja glorificada, assim como também entre vós;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 3, 2, 'E para que sejamos livres de homens corruptos e maus, porque a fé não [é] de todos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 3, 3, 'Mas fiel é o Senhor, que vos fortalecerá e vos guardará do maligno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 3, 4, 'E confiamos no Senhor quanto a vós, de que vós estais fazendo e continuareis a fazer o que vos mandamos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 3, 5, 'E o Senhor guie vossos corações para o amor de Deus e a paciência de Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 3, 6, 'Mas nós vos mandamos, irmãos, no nome de nosso Senhor Jesus Cristo, que mantenhais distância de todo irmão que anda desordenadamente, e não segundo a tradição que recebeu de nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 3, 7, 'Porque vós mesmos sabeis como deveis nos imitar; porque nós não fomos desordenados entre vós;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 3, 8, 'Nem comemos de graça o pão de qualquer um, mas sim com trabalho e cansaço trabalhamos de noite e de dia, para não sermos incômodos a nenhum de vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 3, 9, 'Não porque não tivéssemos autoridade [para fazer isso] , mas porque nós mesmos dávamos exemplo a vós, para [assim] nos imitardes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 3, 10, 'Porque, quando ainda estávamos convosco, isto vos mandamos: que se alguém não quiser trabalhar, também não coma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 3, 11, 'Porque ouvimos que alguns entre vós andam desordenadamente, não trabalhando, mas se intrometendo no que os outros fazem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 3, 12, 'Mas aos tais mandamos e exortamos, por nosso Senhor Jesus Cristo, que trabalhem sem causar incômodo, e comam seu próprio pão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 3, 13, 'E vós, irmãos, não vos canseis de fazer o bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 3, 14, 'Mas se alguém não obedecer à nossa palavra [contida] nesta carta, adverti-o, e não vos mistureis com ele, para que ele se envergonhe;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 3, 15, 'E não o considereis como inimigo, mas alertai [-o] como um irmão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 3, 16, 'E o mesmo Senhor da paz vos dê sempre paz em toda maneira. O Senhor [seja] com todos vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 3, 17, 'A saudação de minha própria mão, Paulo, que é [minha] assinatura em toda carta; assim escrevo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 53, '2 Tessalonicenses', '2Ts', 3, 18, 'A graça de nosso Senhor Jesus Cristo [seja] com todos vós. Amém. [A segunda carta aos tessalonicenses foi escrita de Atenas]'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 1, 1, 'Paulo, apóstolo de Jesus Cristo segundo o mandado de Deus, nosso Salvador, e do Senhor Jesus Cristo, nossa esperança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 1, 2, 'Para Timóteo, [meu] verdadeiro filho na fé. Graça, misericórdia [e] paz da parte de Deus, nosso Pai, e de Cristo Jesus, nosso Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 1, 3, 'Assim como te roguei quando eu estava indo à Macedônia, fica em Éfeso, para advertires a alguns que não ensinem outra doutrina,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 1, 4, 'Nem prestem atenção a mitos nem a genealogias intermináveis, que mais produzem discussões que a edificação da parte de Deus na fé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 1, 5, 'O fim do mandamento é o amor que vem de um coração puro, e de uma boa consciência, e de uma fé não fingida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 1, 6, 'Alguns se desviaram dessas coisas, e se entregaram a discursos inúteis;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 1, 7, 'querendo ser mestres da Lei, mas não entendendo, nem o que dizem, nem o que afirmam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 1, 8, 'Nós, porém, sabemos que a Lei é boa, se alguém usa dela legitimamente;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 1, 9, 'pois sabemos isto: que a Lei não foi feita para o justo, mas sim, para os injustos e insubordinados, para os ímpios e pecadores, para os irreligiosos e profanos, para os matadores dos pais e das mães, para os homicidas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 1, 10, 'para os que cometem pecados sexuais, para os homens que efetuam sexualidade com homens, para os que roubam a liberdade das pessoas, para os mentirosos, para os que juram falsamente, e qualquer outra coisa contrária à sã doutrina,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 1, 11, 'conforme o evangelho da glória do Deus bendito, que foi confiado a mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 1, 12, 'E agradeço àquele que tem me fortalecido, Cristo Jesus, nosso Senhor, porque me considerou fiel, pondo-me no serviço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 1, 13, 'Antes eu era um blasfemo, perseguidor, e opressor; porém recebi misericórdia, pois foi por ignorância que eu agia com incredulidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 1, 14, 'Mas a graça do nosso Senhor Jesus Cristo foi mais abundante, com a fé e amor que há em Cristo Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 1, 15, 'Esta é uma palavra fiel e digna de toda aceitação: que Cristo Jesus veio ao mundo para salvar os pecadores, dos quais eu sou o principal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 1, 16, 'Mas por isso me foi concedida misericórdia, para que em mim, o principal, Jesus Cristo mostrasse toda a sua paciência como exemplo aos que haviam de crer nele para a vida eterna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 1, 17, 'Ao Rei dos tempos, imortal, invisível, o único Deus sábio,[seja] a honra, e a glória, para todo o sempre, amém!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 1, 18, 'Este mandamento, filho Timóteo, te dou: que, conforme as profecias antes feitas acerca de ti, que batalhes por elas a boa batalha;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 1, 19, 'mantendo a fé e a boa consciência, que alguns rejeitaram, e naufragaram na fé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 1, 20, 'Dentre esses foram Himeneu e Alexandre. Eu os entreguei a Satanás, para aprenderem a não blasfemar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 2, 1, 'Por isso eu te exorto, antes de tudo, que se façam pedidos, orações, intercessões [e] atos de gratidão por todas as pessoas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 2, 2, 'pelos reis, e por todos os que estão em posição superior, para que tenhamos uma vida quieta e sossegada, em toda devoção divina e honestidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 2, 3, 'Pois isso é bom e agradável diante de Deus nosso Salvador;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 2, 4, 'que quer que todas as pessoas se salvem e venham ao conhecimento da verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 2, 5, 'Pois [há] um só Deus, e um só Mediador entre Deus e os seres humanos: o humano Cristo Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 2, 6, 'Ele mesmo se deu como resgate por todos, [como] testemunho ao seu tempo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 2, 7, 'Para isso fui constituído pregador e apóstolo, instrutor dos gentios na fé e na verdade (estou dizendo a verdade em Cristo, não mentindo).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 2, 8, 'Portanto, quero que os homens orem em todo lugar, levantando mãos santas, sem ira nem briga.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 2, 9, 'De semelhante maneira, as mulheres se adornem com roupa respeitosa, com pudor e sobriedade, não com tranças, ouro, pérolas, ou roupas caras;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 2, 10, 'mas sim, com boas obras, como é adequado às mulheres que declaram reverência a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 2, 11, 'A mulher aprenda quietamente, com toda submissão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 2, 12, 'Porém não permito que a mulher ensine, nem use de autoridade sobre o marido, mas sim, que esteja em silêncio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 2, 13, 'Pois primeiro foi formado Adão, depois Eva.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 2, 14, 'E Adão não foi enganado; mas a mulher foi enganada, e caiu em transgressão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 2, 15, 'Porém ela se salvará tendo parto, se permanecerem na fé, amor, e santificação com sobriedade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 3, 1, '[Esta] palavra [é] fiel: se alguém deseja ser bispo, deseja uma excelente obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 3, 2, 'É dever, portanto, que o bispo seja irrepreensível, marido de uma mulher, sóbrio, comedido, decente, hospitaleiro, apto para ensinar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 3, 3, 'Não dado ao vinho, não violento, não ganancioso, mas sim moderado, não briguento, não cobiçoso por dinheiro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 3, 4, 'que governe bem a sua própria casa, e tenha os [seus] filhos em submissão com toda dignidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 3, 5, '(Pois, se alguém não sabe governar a sua própria casa, como cuidará da igreja de Deus?)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 3, 6, 'Não um novo convertido; para que não se torne arrogante, e caia na condenação do diabo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 3, 7, 'É dever também que tenha bom testemunho dos que estão de fora, para que não caia em reprovação pública e na cilada do diabo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 3, 8, 'De maneira semelhante, os diáconos sejam de boa conduta, não contraditórios, não dados a muito vinho, não cobiçosos de ganho desonesto,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 3, 9, 'mas mantenham o mistério da fé em consciência pura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 3, 10, 'E também esses sejam primeiro testados, depois sirvam, se forem irrepreensíveis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 3, 11, 'De semelhante maneira, as mulheres [sejam] de boa conduta, não maldizentes, sóbrias, [e] fiéis em todas as coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 3, 12, 'Os diáconos sejam maridos de uma mulher, e governem bem os filhos e as suas próprias casas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 3, 13, 'Pois os que servirem bem obtêm para si uma posição honrosa e muita confiança na fé que há em Cristo Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 3, 14, 'Escrevo-te essas coisas esperando ir a ti em breve;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 3, 15, 'mas, seu eu demorar, para que saibais como se deve comportar na casa de Deus, que é a igreja do Deus vivo, a coluna e o alicerce da verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 3, 16, 'E, sem dúvida nenhuma, grande é o mistério da devoção divina: Deus foi revelado em carne, justificado em Espírito, visto pelos anjos, pregado aos gentios, crido no mundo, e recebido acima em glória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 4, 1, 'Mas o Espírito diz expressamente que nos últimos tempos alguns se afastarão da fé, dando atenção a espíritos enganadores, e a doutrinas de demônios,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 4, 2, 'por meio da hipocrisia de mentirosos, que têm a sua própria consciência cauterizada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 4, 3, 'Eles proibirão o casamento, e [mandarão] se abster dos alimentos que Deus criou para que sejam usados com gratidão pelos fiéis e pelos que conheceram a verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 4, 4, 'Pois toda criatura de Deus é boa, e não há nada a rejeitar, se for recebida com gratidão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 4, 5, 'Porque ela é santificada pela palavra de Deus e [pela] oração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 4, 6, 'Se informares essas coisas aos irmãos, serás um bom servidor de Jesus Cristo, alimentado com as palavras da fé e de boa doutrina que tens seguido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 4, 7, 'Mas rejeita os mitos profanos e de velhas, e exercita-te na devoção divina.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 4, 8, 'Pois o exercício do corpo tem pouco proveito; mas a devoção divina é proveitosa para tudo, pois tem as promessas da vida atual e da futura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 4, 9, '[Esta] palavra é fiel, e digna de toda aceitação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 4, 10, 'Pois para isto também trabalhamos e somos insultados, porque esperamos o Deus vivo, que é o Salvador de todos, especialmente dos crentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 4, 11, 'Manda essas coisas, e ensina.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 4, 12, 'Ninguém despreze a tua juventude, mas sê exemplo aos crentes, na palavra, no comportamento, no amor, em espírito, na fé, e na pureza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 4, 13, 'Persiste na leitura, na exortação e no ensino, até que eu venha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 4, 14, 'Não desprezes o dom que está em ti, que te foi dado por profecia, com a imposição das mãos dos presbíteros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 4, 15, 'Medita nessas coisas, e nelas te ocupe, para que o teu progresso seja visível por todos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 4, 16, 'Tem cuidado de ti mesmo e da doutrina; persevera nessas coisas; porque, se fizeres isso, salvarás tanto a ti mesmo como aos que te ouvem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 5, 1, 'Não repreendas ao idoso asperamente, mas exorta-o como a um pai; aos jovens, como a irmãos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 5, 2, 'às idosas, como a mães; e às moças, como a irmãs, em toda pureza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 5, 3, 'Honra as viúvas que são verdadeiramente viúvas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 5, 4, 'Mas, se alguma viúva tiver filhos ou netos, aprendam primeiro a exercer piedade com a sua própria família, e a recompensar os seus pais; porque isso é bom e agradável diante de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 5, 5, 'A que é verdadeiramente viúva e desamparada espera em Deus, e persevera noite e dia em rogos e orações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 5, 6, 'Mas a que se entrega aos prazeres, enquanto vive, está morta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 5, 7, 'Manda, pois, essas coisas, para que sejam irrepreensíveis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 5, 8, 'Porém, se alguém não cuida dos seus, e principalmente dos de sua própria família, negou a fé, e é pior que um incrédulo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 5, 9, 'A viúva, para ser registrada, não deve ter menos de sessenta anos, e haver sido mulher de um marido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 5, 10, 'Ela deve ter testemunho de boas obras: se criou filhos, se foi hospitaleira, se lavou os pés dos santos, se socorreu os aflitos, se seguiu toda boa obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 5, 11, 'Mas não admitas as viúvas jovens; porque, quando têm desejos sensuais contra Cristo, querem se casar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 5, 12, 'e têm condenação, por haverem anulado a primeira fé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 5, 13, 'E, além disso, também aprendem a andar ociosas de casa em casa; e não somente ociosas, mas também fofoqueiras e curiosas, falando o que não se deve.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 5, 14, 'Por isso, quero que as mais jovens se casem, gerem filhos, administrem a casa, [e] não deem nenhuma oportunidade ao adversário de maldizer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 5, 15, 'Pois algumas já se desviaram e seguiram Satanás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 5, 16, 'Se algum crente ou alguma crente tem viúvas, que as ajude, e não sobrecarregue a igreja, para que ela possa ajudar as que são de verdade viúvas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 5, 17, 'Os presbíteros [ou: anciãos] que lideram bem sejam estimados como dignos de honra dobrada, principalmente os que trabalham na palavra e na doutrina.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 5, 18, 'Pois a Escritura diz: “Ao boi que debulha não atarás a boca”; e: “o trabalhador é digno do seu salário”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 5, 19, 'Não aceites acusação contra um presbítero, a não ser com duas ou três testemunhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 5, 20, 'Aos que pecarem, repreende-os na presença de todos, para que os outros também tenham temor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 5, 21, 'Ordeno-te, diante de Deus, do Senhor Jesus Cristo, e dos anjos escolhidos, que guardes essas coisas sem preconceitos, fazendo nada por favoritismo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 5, 22, 'A ninguém imponhas as mãos apressadamente, nem participes dos pecados alheios; conserva-te puro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 5, 23, 'Não bebas mais [somente] água, mas usa [também] de um pouco de vinho, por causa do teu estômago, e das tuas frequentes enfermidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 5, 24, 'Os pecados de algumas pessoas são evidentes antes mesmo do juízo, mas os de algumas são manifestos depois.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 5, 25, 'Semelhantemente, também, as boas obras são evidentes; e as que não são assim não se podem esconder.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 6, 1, 'Todos os servos que estão sob escravidão estimem aos seus senhores como dignos de toda honra; para que o nome de Deus e a doutrina não sejam blasfemados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 6, 2, 'E os que têm senhores crentes não os desprezem por serem irmãos; pelo contrário, que os sirvam melhor, pois os participantes do benefício são crentes e amados. Ensina e exorta estas coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 6, 3, 'Se alguém ensina doutrina diferente, e não concorda com as sãs palavras do nosso Senhor Jesus Cristo e com a doutrina que é conforme a devoção divina,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 6, 4, 'é presunçoso, e nada sabe. Em vez disso, se interessa de maneira doentia por questões e disputas de palavras, das quais nascem invejas, brigas, blasfêmias, suspeitas maldosas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 6, 5, 'discussões inúteis de pessoas corrompidas de entendimento, e privadas da verdade, que pensam que a devoção divina é um meio de lucrar. Afasta-te dos tais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 6, 6, 'Mas grande lucro é a devoção divina acompanhada de contentamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 6, 7, 'Pois nada trouxemos ao mundo, e [é] evidente que nada podemos levar dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 6, 8, 'Mas se tivermos alimento e algo com que nos cobrirmos, estejamos contentes com isso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 6, 9, 'Mas os que querem ser ricos caem em tentação, armadilha, e em muitos desejos insensatos e nocivos, que afundam as pessoas na destruição e perdição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 6, 10, 'Pois o amor ao dinheiro é raiz de todos os tipos de males. Alguns o cobiçam, e então se desviaram da fé, e perfuraram a si mesmos com muitas dores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 6, 11, 'Porém tu, homem de Deus, foge dessas coisas. Segue a justiça, a devoção divina, a fé, o amor, a paciência, a mansidão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 6, 12, 'Que lutes a boa luta da fé; agarra a vida eterna para a qual também foste chamado, e confessaste a boa confissão diante de muitas testemunhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 6, 13, 'Mando-te diante de Deus, que dá vida a todas as coisas, e de Cristo Jesus, que diante de Pôncio Pilatos testemunhou a boa confissão,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 6, 14, 'que guardes este mandamento sem mancha nem motivo de repreensão, até a aparição do nosso Senhor Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 6, 15, 'Essa nos seus tempos mostrará o bendito e único Soberano, o Rei dos reis, e Senhor dos senhores;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 6, 16, 'o único a ter imortalidade, e que habita em luz inacessível; aquele a quem nenhum ser humano viu, nem pode ver; a ele seja honra e poder para sempre! Amém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 6, 17, 'Manda aos ricos desta era que não sejam soberbos, nem ponham a esperança na incerteza das riquezas, mas sim no Deus vivo, que nos dá abundantemente todas as coisas [que são] para alegria;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 6, 18, 'que façam o bem, sejam ricos em boas obras, dispostos a compartilhar, e generosos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 6, 19, 'que acumulem para si mesmos um bom fundamento para o futuro, para que obtenham a vida eterna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 6, 20, 'Timóteo, guarda o depósito que [te] foi confiado, evitando conversas vãs e profanas, e controvérsias do que é falsamente chamado de “conhecimento”;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 54, '1 Timóteo', '1Tm', 6, 21, 'que alguns declararam seguir, e se desviaram da fé. A graça [seja] contigo. Amém. [A primeira carta a Timóteo foi escrita de Laodiceia, que é a principal cidade da Frígia Pacaciana] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 1, 1, 'Paulo, apóstolo de Jesus Cristo, pela vontade de Deus, segundo a promessa da vida que está em Cristo Jesus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 1, 2, 'a Timóteo, [meu] amado filho. Graça, misericórdia, [e] paz, da parte de Deus Pai, e de Cristo Jesus, nosso Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 1, 3, 'Agradeço a Deus, a quem desde os [meus] antepassados sirvo com uma consciência pura, de que sem cessar tenho memória de ti nas minhas orações noite e dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 1, 4, 'Lembro-me das tuas lágrimas, e desejo muito te ver, para me encher de alegria;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 1, 5, 'Trago à memória a fé não fingida que há em ti, [fé] que habitou primeiro na tua avó Loide, e na tua mãe Eunice; e tenho certeza que também em ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 1, 6, 'Por essa causa lembro-te de reacenderes o dom de Deus que está em ti pela imposição das minhas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 1, 7, 'Pois Deus não nos deu espírito de medo; mas sim de força, de amor, e de moderação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 1, 8, 'Portanto não te envergonhes do testemunho do nosso Senhor, nem de mim, que sou prisioneiro dele; em vez disso, participa das aflições do Evangelho segundo o poder de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 1, 9, 'Ele nos salvou, e chamou com um chamado santo; não conforme as nossas obras, mas sim, conforme a sua própria intenção, e a graça que nos foi dada em Cristo Jesus antes dos princípios dos tempos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 1, 10, 'mas agora é manifesta pela aparição do nosso Salvador Jesus Cristo, que anulou a morte, e trouxe para a luz a vida e a imortalidade por meio do evangelho;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 1, 11, 'do qual eu fui constituído pregador e apóstolo, e instrutor dos gentios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 1, 12, 'Por causa disso também sofro essas coisas; porém não me envergonho. Pois sei em quem tenho crido, e tenho certeza de que ele é poderoso para guardar o que lhe confiei até aquele dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 1, 13, 'Preserva o exemplo das sãs palavras que tens ouvido de mim, na fé e no amor que [há] em Cristo Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 1, 14, 'Guarda o bem que te foi confiado por meio do Espírito Santo que habita em nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 1, 15, 'Sabes isto, que todos os que estão na Ásia Romana me abandonaram, entre os quais estavam Fígelo e Hermógenes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 1, 16, 'O Senhor conceda misericórdia à casa de Onesíforo, pois muitas vezes ele me consolou, e não se envergonhou de eu estar em cadeias;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 1, 17, 'Pelo contrário, quando veio a Roma, com empenho me procurou, e [me] encontrou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 1, 18, 'O Senhor lhe conceda que naquele dia ele encontre misericórdia diante do Senhor. E tu sabes muito bem como ele [me] ajudou em Éfeso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 2, 1, 'Portanto tu, meu filho, fortifica-te na graça que há em Cristo Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 2, 2, 'E o que de mim ouviste entre muitas testemunhas, confia-o a pessoas fiéis, que sejam competentes para ensinar também a outros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 2, 3, 'Tu, pois, sofre as aflições como bom soldado de Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 2, 4, 'Nenhum soldado em batalha se envolve com assuntos desta vida, pois tem como objetivo agradar àquele que o alistou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 2, 5, 'E, também, se alguém está competindo como atleta, não recebe a coroa se não seguir as regras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 2, 6, 'O lavrador que trabalha deve ser o primeiro a receber da partilha dos frutos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 2, 7, 'Considera o que digo; que o Senhor te dê entendimento em tudo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 2, 8, 'Lembra-te de Jesus Cristo, ressuscitado dos mortos, da descendência de Davi, segundo o meu evangelho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 2, 9, 'Por esse [evangelho] sofro aflições, e até prisões, como um criminoso; mas a palavra de Deus não está presa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 2, 10, 'Por isso tudo suporto por causa dos escolhidos, a fim de que também eles obtenham a salvação que está em Cristo Jesus com glória eterna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 2, 11, 'Esta afirmação [é] fiel: se morrermos com [ele] , também com [ele] viveremos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 2, 12, 'se sofrermos, também com [ele] reinaremos; se o negamos, também ele nos negará;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 2, 13, 'se formos infiéis, ele continua fiel; ele não pode negar a si mesmo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 2, 14, 'Lembra-os disso, alertando-os diante do Senhor, que não tenham brigas de palavras, que não têm proveito algum, [a não ser] para a ruína dos ouvintes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 2, 15, 'Procura apresentar-te aprovado a Deus[como] um trabalhador que não tem de que se envergonhar, que usa bem a palavra da verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 2, 16, 'Mas evita conversas profanas [e] inútes; pois tendem a produzir maior irreverência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 2, 17, 'E a palavra deles se espalhará como uma gangrena; entre os quais são Himeneu e Fileto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 2, 18, 'Esses se desviaram da verdade, dizendo que a ressurreição já aconteceu; e perverteram a fé de alguns.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 2, 19, 'Porém o fundamento de Deus continua firme, e tem este selo: o Senhor conhece os que são seus, e que todo aquele que faz uso do nome de Cristo, se afaste da injustiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 2, 20, 'Numa grande casa não há somente utensílios de ouro e de prata, mas também de madeira e de barro; e uns para honra, porém outros para desonra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 2, 21, 'Portanto, se alguém se purificar destas coisas, será utensílio para honra, santificado e adequado para uso do Dono, [e] preparado para toda boa obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 2, 22, 'Foge também dos desejos da juventude; e segue a justiça, a fé, o amor, [e] a paz, com os que, de coração puro, invocam o Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 2, 23, 'E rejeita as questões tolas e sem instrução, como sabes que elas produzem brigas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 2, 24, 'E ao servo do Senhor não convém brigar, mas sim ser manso com todos, apto para ensinar e suportar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 2, 25, 'deve instruir com mansidão aos que se opõem, pois talvez Deus lhes dê arrependimento para conhecerem a verdade;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 2, 26, 'e se libertem da armadilha do diabo, em que foram presos à vontade dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 3, 1, 'Sabe porém isto, que nos últimos dias virão tempos difíceis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 3, 2, 'Pois haverá alguns que serão egoístas, gananciosos, presunçosos, soberbos, blasfemos, desobedientes a pais e a mães, ingratos, profanos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 3, 3, 'sem afeto natural, irreconciliáveis, caluniadores, sem dominio próprio, cruéis, sem amor com os bons,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 3, 4, 'traidores, precipitados, orgulhosos, que amam mais os prazeres que a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 3, 5, 'Eles têm uma aparência de devoção divina, mas negam o poder dela. Afasta-te desses também.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 3, 6, 'Pois dentre esses são os que entram pelas casas, e levam cativas as mulheres insensatas carregadas de pecados, levadas com vários maus desejos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 3, 7, 'que sempre estão aprendendo, e jamais conseguem chegar ao conhecimento da verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 3, 8, 'E assim como Janes e Jambres se opuseram a Moisés, assim também esses se opõem a verdade; esses são corruptos de entendimento, e reprovados quanto à fé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 3, 9, 'Eles, porém, não avançarão; pois a insensatez deles será evidente a todos, como também foi a daqueles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 3, 10, 'Porém tu tens seguido a minha doutrina, conduta, intenção, fé, paciência, amor, perseverança,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 3, 11, 'perseguições, aflições; as quais me aconteceram em Antioquia, em Icônio e em Listra; tais perseguições sofri, e o Senhor me livrou de todas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 3, 12, 'E também todos os que querem viver devotamente em Cristo Jesus sofrerão perseguição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 3, 13, 'Mas os que são maus e enganadores irão de mal a pior, enganando e sendo enganados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 3, 14, 'Tu, porém, continua nas coisas que aprendeste e das quais foste convencido, pois sabes de quem as aprendeste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 3, 15, 'e que desde tua infância conheceste as Sagradas Escrituras, que podem te fazer sábio para a salvação pela fé em Cristo Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 3, 16, 'Toda a Escritura [é] divinamente inspirada e proveitosa para ensinar, para mostrar erros, para corrigir, e para instruir na justiça;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 3, 17, 'para que o homem de Deus seja completo, plenamente instruído para toda boa obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 4, 1, 'Portanto te convoco diante de Deus e do Senhor Jesus Cristo, que irá julgar os vivos e os mortos em sua aparição e seu reino:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 4, 2, 'prega a palavra; insiste em tempo e fora de tempo; mostra os erros; repreende [e] exorta, com toda paciência e ensino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 4, 3, 'Pois virá tempo em que não suportarão a sã doutrina; em vez disso, terão comichão no ouvido e amontoarão para si instrutores conforme os seus próprios desejos maus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 4, 4, 'desviarão os ouvidos da verdade, e se voltarão aos mitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 4, 5, 'Tu, porém, vigia-te em todas as coisas; suporta as aflições, faz a obra de evangelista, cumpre o teu serviço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 4, 6, 'Pois já sou uma oferta de derramamento, e o tempo da minha partida está perto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 4, 7, 'Lutei a boa luta, terminei a carreira, guardei a fé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 4, 8, 'Desde agora a coroa da justiça me está reservada, a qual o Senhor, o justo Juiz, me dará naquele dia; e não somente a mim, mas também a todos os que amarem a sua vinda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 4, 9, 'Procura vir logo até mim,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 4, 10, 'porque Demas me desamparou: ele amou o tempo presente, e partiu para Tessalônica; Crescente para a Galácia, e Tito para a Dalmácia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 4, 11, 'Só Lucas está comigo. Toma Marcos, e o traz contigo, porque ele me é muito útil para o serviço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 4, 12, 'Enviei Tíquico a Éfeso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 4, 13, 'Quando vieres, traz a capa que deixei em Trôade na casa de Carpo, e os livros, principalmente os pergaminhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 4, 14, 'Alexandre, o que trabalha com cobre, me causou muitos males; o Senhor retribua a ele conforme suas obras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 4, 15, 'Toma cuidado com ele também, porque ele se opôs muito às nossas palavras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 4, 16, 'Na minha primeira defesa ninguém esteve comigo para me ajudar, pelo contrário, todos me desampararam. Que isso não seja levado em consideração contra eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 4, 17, 'Mas o Senhor me ajudou e me fortaleceu, a fim de que por mim a pregação fosse completamente divulgada, e todos os gentios [a] ouvissem; e fui livrado da boca do leão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 4, 18, 'E o Senhor me livrará de toda obra má, e me preservará para o seu reino celestial. A ele [seja] glória para todo o sempre. Amém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 4, 19, 'Cumprimenta Prisca e Áquila, e a casa de Onesíforo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 4, 20, 'Erasto ficou em Corinto, e deixei Trófimo doente em Mileto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 4, 21, 'Procura vir antes do inverno. Êubulo, Pudente, Lino, Cláudia e todos os irmãos te cumprimentam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 55, '2 Timóteo', '2Tm', 4, 22, 'O Senhor Jesus Cristo seja com o teu espírito. A graça seja convosco. Amém.[A segunda carta a Timóteo (o primeiro bispo escolhido para a igreja dos efésios) foi escrita em Roma, quando Paulo foi apresentado pela segunda vez ao imperador Nero]'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 1, 1, 'Paulo, servo de Deus e apóstolo de Jesus Cristo, segundo a fé dos escolhidos de Deus, e o conhecimento da verdade, que é segundo a devoção divina;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 1, 2, 'em esperança da vida eterna, a qual Deus, que não pode mentir, prometeu antes dos princípios dos tempos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 1, 3, 'E a seu [devido] tempo [a] manifestou: a sua palavra, por meio da pregação, que me foi confiada segundo o mandamento de Deus nosso Salvador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 1, 4, 'Para Tito, [meu] verdadeiro filho, segundo a fé em comum; [haja em ti] graça, misericórdia [e] paz de Deus Pai, e do Senhor Jesus Cristo, nosso Salvador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 1, 5, 'Por esta causa eu te deixei em Creta, para que tu continuasses a pôr em ordem as coisas que estavam faltando, e de cidade em cidade constituísses presbíteros, conforme eu te mandei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 1, 6, 'Se alguém for irrepreensível, marido de uma mulher, que tenha filhos fiéis, que não possam ser acusados de serem devassos ou desobedientes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 1, 7, 'Porque o supervisor deve ser irrepreensível, como administrador da casa de Deus, não arrogante, que não se ira facilmente, não beberrão, não agressivo, nem ganancioso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 1, 8, 'Mas [que ele seja] hospitaleiro, ame aquilo que é bom, moderado, justo, santo, [e] tenha domínio próprio;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 1, 9, 'Retendo firme a fiel palavra que é conforme o que foi ensinado; para que ele seja capaz, tanto para exortar na sã doutrina, como [também] para mostrar os erros dos que falam contra [ela] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 1, 10, 'Porque também há muitos insubordinados, que falam coisas vãs, e enganadores, especialmente aqueles da circuncisão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 1, 11, 'Aos quais devem se calar, que transtornam casas inteiras, ensinando o que não se deve, por causa da ganância.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 1, 12, 'Um próprio profeta deles disse: Os cretenses sempre são mentirosos, animais malignos, ventres preguiçosos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 1, 13, 'Este testemunho é verdadeiro; por isso repreende-os severamente, para que sejam sãos na fé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 1, 14, 'Não dando atenção a mitos judaicos, e a mandamentos de homens, que desviam da verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 1, 15, 'Realmente todas as coisas são puras para os puros; mas para os contaminados e infiéis, nada é puro; e até o entendimento e a consciência deles estão contaminados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 1, 16, 'Eles declaram que conhecem a Deus, mas com as obras eles o negam, pois são abomináveis e desobedientes, e reprovados para toda boa obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 2, 1, 'Tu, porém, fala o que convém à sã doutrina;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 2, 2, 'Aos velhos, que sejam sóbrios, respeitáveis, prudentes, sãos na fé, no amor e na paciência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 2, 3, 'Às velhas, da mesma maneira, [tenham] bons costumes, como convém a santas; não caluniadoras, não viciadas em muito vinho, mas sim instrutoras daquilo que é bom;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 2, 4, 'Para ensinarem às moças a serem prudentes, a amarem a seus maridos, a amarem a seus filhos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 2, 5, 'A serem moderadas, puras, boas donas de casa, sujeitas a seus próprios maridos, para que a palavra de Deus não seja blasfemada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 2, 6, 'Exorta semelhantemente aos rapazes, que sejam moderados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 2, 7, 'Em tudo mostra a ti mesmo como exemplo de boas obras; na doutrina, [mostra] incorrupção, dignidade, sinceridade;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 2, 8, 'Uma palavra sã [e] irrepreensível, para que [qualquer] opositor se envergonhe, nada tendo de mal para dizer contra vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 2, 9, 'Que os servos sejam sujeitos a seus próprios senhores, sendo agradáveis em tudo, [e] não falando contra [eles] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 2, 10, 'Não [lhes] furtando, mas sim mostrando toda a boa lealdade; para que em tudo adornem a doutrina de Deus nosso Salvador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 2, 11, 'Porque a graça salvadora de Deus se manifestou a todos os homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 2, 12, 'Ensinando-nos que, ao renunciarmos à irreverência e aos maus desejos mundanos, vivamos neste tempo presente de maneira sóbria, justa e devota.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 2, 13, 'Aguardando a bem-aventurada esperança e o aparecimento da glória do grande Deus e nosso Salvador Jesus Cristo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 2, 14, 'O qual deu a si mesmo por nós, para nos libertar de toda injustiça, e para purificar para si mesmo um povo particular, zeloso de boas obras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 2, 15, 'Fala estas coisas, exorta, e repreende com toda autoridade. Ninguém te despreze.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 3, 1, 'Relembra-os para se sujeitarem aos governantes e às autoridades, sejam obedientes, [e] estejam preparados para toda boa obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 3, 2, 'Não insultem a ninguém, não sejam briguentos, [mas sim] pacientes, mostrando toda mansidão para com todos os homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 3, 3, 'Porque nós também éramos tolos, desobedientes, enganados, servindo a vários maus desejos e prazeres, vivendo em malícia e inveja, detestáveis, odiando uns aos outros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 3, 4, 'Mas quando a bondade e amor de Deus nosso Salvador para a humanidade apareceu,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 3, 5, 'Não pelas obras de justiça que nós tivéssemos feito, mas sim segundo sua misericórdia, ele nos salvou pelo banho do novo nascimento, e da renovação do Espírito Santo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 3, 6, 'Ao qual ele derramou abundantemente em nós por meio de Jesus Cristo nosso Salvador;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 3, 7, 'Para que, ao termos sido justificados por sua graça, sejamos feitos herdeiros segundo a esperança da vida eterna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 3, 8, '[Esta] palavra [é] fiel, e isto quero que insistas em confirmar, para que os que creem em Deus procurem se dedicar às boas obras; estas coisas são boas e proveitosas aos homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 3, 9, 'Mas evita as questões tolas, e às genealogias e discussões, e às disputas quanto à Lei, porque elas são inúteis e vás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 3, 10, 'Ao homem rebelde, depois da primeira e [da] segunda repreensão, rejeita [-o] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 3, 11, 'Sabendo que o tal está pervertido, e está pecando, estando a si mesmo condenado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 3, 12, 'Quando eu enviar Artemas até ti, ou Tíquico, procura vir até mim a Nicópolis, porque eu decidi passar lá o inverno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 3, 13, 'Auxilia com empenho a Zenas, o especialista na Lei, e a Apolo, na viagem deles, para que nada lhes falte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 3, 14, 'E que também os nossos aprendam a se dedicarem às boas obras para os usos necessários, para que não sejam infrutíferos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 56, 'Tito', 'Tt', 3, 15, 'Todos os que estão comigo te saúdam. Saúda tu aos que nos amam na fé. A graça [seja] com todos vós. Amém! [A carta a Tito, o primeiro bispo escolhido da igreja dos cretenses, foi escrita de Nicópolis na Macedônia]'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 57, 'Filemom', 'Fm', 1, 1, 'Paulo, prisioneiro de Cristo Jesus, e o irmão Timóteo, a Filemom, o amado, e nosso cooperador;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 57, 'Filemom', 'Fm', 1, 2, 'E à amada Ápia, e a Arquipo nosso companheiro de batalha, e à igreja [que está] em tua casa;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 57, 'Filemom', 'Fm', 1, 3, '[Haja] em vós graça e paz de Deus nosso Pai, e do Senhor Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 57, 'Filemom', 'Fm', 1, 4, 'Eu dou graças a meu Deus sempre me lembrando de ti em minhas orações;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 57, 'Filemom', 'Fm', 1, 5, 'Ao ouvir de teu amor e a fé que tu tens para com o Senhor Jesus, e para com todos os santos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 57, 'Filemom', 'Fm', 1, 6, 'Para que a comunhão de tua fé seja eficaz no reconhecimento de todo o bem que há em vós por Cristo Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 57, 'Filemom', 'Fm', 1, 7, 'Porque nós temos grande alegria e consolo em teu amor, pelo qual, por meio de ti, irmão, os sentimentos dos santos foram aliviados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 57, 'Filemom', 'Fm', 1, 8, 'Por isso, ainda que em Cristo eu tenha grande confiança para te mandar [aquilo que te é] conveniente,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 57, 'Filemom', 'Fm', 1, 9, 'Em vez disso por amor eu [te] peço, [ainda que] eu seja tal, Paulo, o velho, e também agora um prisioneiro de Jesus Cristo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 57, 'Filemom', 'Fm', 1, 10, 'Eu te peço por meu filho Onésimo, ao qual eu gerei durante minhas prisões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 57, 'Filemom', 'Fm', 1, 11, 'Aquele que antes te era inútil, mas agora útil para mim e para ti, eu o enviei de volta;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 57, 'Filemom', 'Fm', 1, 12, 'E tu, como os meus mais íntimos sentimentos, recebe-o;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 57, 'Filemom', 'Fm', 1, 13, 'Eu [até que] gostaria de retê-lo comigo, para que como teu [substituto] ele me servisse nas prisões do Evangelho;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 57, 'Filemom', 'Fm', 1, 14, 'Mas eu nada quis fazer sem tua opinião, para que tua bondade não fosse como que por obrigação, mas sim de livre vontade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 57, 'Filemom', 'Fm', 1, 15, 'Porque talvez por isso que ele tenha se separado [de ti] por algum tempo, para que tu o recebesses de volta para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 57, 'Filemom', 'Fm', 1, 16, 'Não mais como a um servo, mas sim mais que um servo, [como] a um amado irmão, especialmente para mim, e muito mais de ti, tanto na carne como no Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 57, 'Filemom', 'Fm', 1, 17, 'Portanto, se tu me tens como companheiro, [então] recebe-o como a mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 57, 'Filemom', 'Fm', 1, 18, 'E se ele te fez algum dano, ou te deve [alguma coisa] ,põe [isto] na minha conta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 57, 'Filemom', 'Fm', 1, 19, 'Eu, Paulo, de minha [própria] mão [o] escrevi, eu pagarei; para eu não te dizer que tu me deves a ti mesmo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 57, 'Filemom', 'Fm', 1, 20, 'Assim, irmão, que eu tenha algum benefício de ti no Senhor; alivia meus sentimentos no Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 57, 'Filemom', 'Fm', 1, 21, 'Tendo confiança de tua obediência eu te escrevi, sabendo que tu farás ainda mais do que eu digo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 57, 'Filemom', 'Fm', 1, 22, 'E enquanto isso também me prepara um lugar para [eu] ficar; porque eu espero que por vossas orações eu seja entregue a vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 57, 'Filemom', 'Fm', 1, 23, 'Saúdam-te: Epafras (meu companheiro de prisão em Cristo Jesus),'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 57, 'Filemom', 'Fm', 1, 24, 'Marcos, Aristarco, Demas [e] Lucas (meus cooperadores).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 57, 'Filemom', 'Fm', 1, 25, 'A graça de nosso Senhor Jesus Cirsto [seja] com vosso espírito. Amém! [Escrita em Roma para Filemom, e enviada pelo servo Onésimo]'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 1, 1, 'Deus falou antigamente muitas vezes, e de muitas maneiras, aos ancestrais pelos profetas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 1, 2, 'Mas nestes últimos falou a nós por meio do [seu] Filho, a quem constituiu por herdeiro de todas as coisas, e pelo qual também fez o universo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 1, 3, '[O Filho] é o resplendor da [sua] glória, a expressa imagem da sua pessoa, e sustenta todas as coisas pela sua palavra de poder. E, depois de fazer por si mesmo a purificação dos nossos pecados, sentou-se à direita da Majestade nas alturas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 1, 4, 'e se tornou muito superior aos anjos, assim como herdou um nome mais excelente que eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 1, 5, 'Pois a qual dos anjos [Deus] jamais disse: “Tu és meu Filho, eu hoje te gerei”, E em outra vez: “Eu lhe serei por Pai, e ele me será por Filho”?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 1, 6, 'E outra vez, quando introduz o primogênito ao mundo, diz: E todos os anjos de Deus o adorem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 1, 7, 'Quanto aos anjos, porém, ele diz: Ele faz de seus anjos espíritos; e de seus trabalhadores, labareda de fogo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 1, 8, 'Mas ao Filho [diz] : Ó Deus, o teu trono é para todo o sempre. Cetro de equidade é o cetro do teu Reino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 1, 9, 'Amaste a justiça, e odiaste a transgressão; por isso, Deus, o teu Deus, te ungiu com óleo de alegria mais que os teus companheiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 1, 10, 'E: Tu Senhor, no princípio fundaste a terra, e os céus são obras de tuas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 1, 11, 'Eles perecerão, mas tu continuas. Todos eles como roupa se envelhecerão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 1, 12, 'como uma manta tu os envolverás, e serão mudados; porém tu és o mesmo, e os teus anos não cessarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 1, 13, 'E a qual dos anjos ele jamais disse: Senta-te à minha direita, até que eu ponha os teus inimigos como estrado de teus pés?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 1, 14, 'Por acaso não são todos eles espíritos servidores, enviados para auxílio dos que herdarão a salvação?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 2, 1, 'Portanto, devemos prestar atenção com muito mais empenho para as coisas que já ouvimos, para que nunca venhamos a cometer deslizes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 2, 2, 'Pois, se a palavra pronunciada pelos anjos foi confirmada, e toda transgressão e desobediência recebeu justa retribuição,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 2, 3, 'como nós escaparemos, se descuidarmos de tão grande salvação? Ela, que começou a ser anunciada pelo Senhor, foi-nos confirmada pelos que ouviram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 2, 4, 'Deus também deu testemunho com eles, por meio de sinais, milagres, várias maravilhas, e distribuições do Espírito Santo, segundo a sua vontade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 2, 5, 'Pois não foi aos anjos que ele sujeitou o mundo futuro, do qual estamos falando.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 2, 6, 'Mas em certo lugar alguém testemunhou, dizendo: O que é o homem, para que te lembres dele? Ou o filho do homem, para que o visites?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 2, 7, 'Tu o fizeste um pouco menor que os anjos, de glória e de honra o coroaste, e o estabeleceste sobre as obras das tuas mãos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 2, 8, 'Sujeitaste todas as coisas debaixo de seus pés.Pois ao lhe sujeitar todas as coisas, nada deixou que não fosse sujeito a ele; porém agora ainda não vemos todas as coisas sendo sujeitas a ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 2, 9, 'Porém vemos coroado de glória e de honra, por causa do sofrimento de morte, aquele Jesus, que havia sido feito um pouco menor que os anjos, a fim de que, pela graça de Deus, experimentasse a morte por todos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 2, 10, 'Pois convinha a aquele, para quem e por quem são todas as coisas, que, quando trouxesse muitos filhos à glória, aperfeiçoasse por meio de aflições o Autor da salvação deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 2, 11, 'Porque tanto o que santifica como os que são santificados, todos são provenientes de um; por isso ele não se envergonha de lhes chamar de irmãos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 2, 12, 'dizendo: Anunciarei o teu nome aos meus irmãos, cantarei louvores a ti no meio da congregação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 2, 13, 'E outra vez: Nele confiarei. E outra vez: Eis-me aqui, com os filhos que Deus me deu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 2, 14, 'Portanto, uma vez que os filhos compartilham da carne e do sangue, também ele, semelhantemente, participou das mesmas coisas, a fim de pela morte aniquilar ao que tinha o poder da morte, isto é, o diabo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 2, 15, 'e libertar a todos os que, por medo da morte, estavam sujeitos à servidão durante a vida toda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 2, 16, 'Pois, evidentemente, não é aos anjos que ele ajuda, mas sim, ajuda à descendência de Abraão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 2, 17, 'Por isso era necessário que em tudo ele se tornasse semelhante aos irmãos, para ser misericordioso e fiel Sumo Sacerdote nas coisas [relativas] a Deus, para fazer sacrifício de perdão dos pecados do povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 2, 18, 'Pois, naquilo em que ele mesmo sofreu ao ser tentado, ele pode socorrer aos que são tentados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 3, 1, 'Portanto, santos irmãos, participantes do chamado celestial, considerai o Apóstolo e Sumo Sacerdote da nossa declaração de fé, Cristo Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 3, 2, 'Ele é fiel àquele que o constituiu, assim como Moisés também foi em toda a casa de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 3, 3, 'Pois ele é estimado como digno de maior glória do que Moisés, assim como mais honra do que a casa tem quem a construiu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 58, 'Hebreus', 'Hb', 3, 4, 'Porque toda casa é construída por alguém; mas aquele que construiu todas as coisas é Deus.')
